#define main historical_main
#include "../laplace3d-cuda/main.cu"
#undef main
#include <vector>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{std::vector<float>x,ref;std::vector<double>gold;float*a,*b;int kind;};
std::vector<double> oracle(std::vector<double>&x,int nx,int ny,int nz){auto out=x;for(int z=1;z<nz-1;z++)for(int y=1;y<ny-1;y++)for(int xx=1;xx<nx-1;xx++){int i=xx+y*nx+z*nx*ny;out[i]=(x[i-1]+x[i+1]+x[i-nx]+x[i+nx]+x[i-nx*ny]+x[i+nx*ny])/6.;}return out;}
int main(int argc,char**argv){int steps=argc>1?atoi(argv[1]):20;if(steps!=20)return 2;int nx=64,ny=19,nz=17,n=nx*ny*nz;std::vector<Case>cases;for(int kind=0;kind<2;kind++){Case c;c.kind=kind;for(int z=0;z<nz;z++)for(int y=0;y<ny;y++)for(int x=0;x<nx;x++)c.x.push_back(kind?float(x+2*y+3*z)/256.f:((x==0||x==nx-1||y==0||y==ny-1||z==0||z==nz-1)?1.f:0.f));c.ref=c.x;c.gold.assign(c.x.begin(),c.x.end());std::vector<float>tmp(n);for(int step=0;step<steps;step++){reference(nx,ny,nz,c.ref.data(),tmp.data());std::swap(c.ref,tmp);c.gold=oracle(c.gold,nx,ny,nz);}CK(cudaMalloc(&c.a,n*4));CK(cudaMalloc(&c.b,n*4));CK(cudaMemcpy(c.a,c.x.data(),n*4,cudaMemcpyHostToDevice));laplace3d<<<dim3(2,3),dim3(32,8)>>>(nx,ny,nz,nx,c.a,c.b);cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0,ma=0,de=0,be=0,he=0;bool ok=true;std::vector<float>output;for(auto&c:cases){CK(cudaMemcpy(c.a,c.x.data(),n*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());float*src=c.a,*dst=c.b;auto start=std::chrono::steady_clock::now();for(int step=0;step<steps;step++){laplace3d<<<dim3(2,3),dim3(32,8)>>>(nx,ny,nz,nx,src,dst);std::swap(src,dst);}CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/steps;std::vector<float>got(n);CK(cudaMemcpy(got.data(),src,n*4,cudaMemcpyDeviceToHost));for(int z=0;z<nz;z++)for(int y=0;y<ny;y++)for(int x=0;x<nx;x++){int i=x+y*nx+z*nx*ny;ma=fmax(ma,fabs(got[i]-c.ref[i]));de=fmax(de,fabs(got[i]-c.gold[i]));if(x==0||x==nx-1||y==0||y==ny-1||z==0||z==nz-1)be=fmax(be,fabs(got[i]-c.x[i]));if(c.kind)he=fmax(he,fabs(got[i]-c.x[i]));ok&=std::isfinite(got[i])&&got[i]>=0&&got[i]<=1&&fabs(got[i]-c.ref[i])<=1e-5&&fabs(got[i]-c.gold[i])<=1e-5;}output.insert(output.end(),got.begin(),got.end());}ok&=be==0&&he<=1e-5;allok&=ok;char file[80];sprintf(file,"laplace3d_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"float64_oracle_max_error\":%.12g,\"boundary_max_error\":%.12g,\"harmonic_fixedpoint_error\":%.12g,\"timing_region\":\"sum_two_20step_relaxations_normalized_per_step\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",output.size(),ma,de,be,he,steps,file,output.size());}for(auto&c:cases){CK(cudaFree(c.a));CK(cudaFree(c.b));}puts(allok?"PASS":"FAIL");return allok?0:1;}
